import { Config, ConfigProvider, Effect, Schema } from "effect";

export const ExecutorConnectionConfigOperation = Schema.Literals([
  "loadEndpoint",
  "loadApiKey",
]);

export class ExecutorConnectionConfigError extends Schema.TaggedErrorClass<ExecutorConnectionConfigError>()(
  "ExecutorConnectionConfigError",
  {
    message: Schema.NonEmptyString,
    operation: ExecutorConnectionConfigOperation,
    reason: Schema.NonEmptyString,
  }
) {}

export const ExecutorMcpEndpoint = Schema.URL.pipe(
  Schema.check(
    Schema.makeFilter((endpoint) => {
      if (endpoint.protocol !== "https:") {
        return "Executor MCP endpoint must use HTTPS.";
      }
      if (endpoint.hostname !== "executor.sh") {
        return "Executor MCP endpoint must use the approved Executor host.";
      }
      if (endpoint.port) {
        return "Executor MCP endpoint must not override the HTTPS port.";
      }
      if (
        !/^\/(?:[a-z0-9-]+\/)?mcp\/toolkits\/[a-z0-9]+(?:-[a-z0-9]+)*$/u.test(
          endpoint.pathname
        )
      ) {
        return "Executor MCP endpoint must identify a dedicated toolkit.";
      }
      if (endpoint.username || endpoint.password || endpoint.hash) {
        return "Executor MCP endpoint must not contain userinfo or a fragment.";
      }
      const modes = endpoint.searchParams.getAll("elicitation_mode");
      if (modes.length !== 1 || modes[0] !== "browser") {
        return "Executor MCP endpoint must select browser elicitation exactly once.";
      }
      if (endpoint.searchParams.has("allow_model_resume")) {
        return "Executor MCP endpoint must not enable legacy model resume.";
      }
      if (
        [...endpoint.searchParams.keys()].some(
          (name) => name !== "elicitation_mode"
        )
      ) {
        return "Executor MCP endpoint contains an unsupported query parameter.";
      }

      return true;
    })
  )
);

const endpointConfig = Config.schema(
  ExecutorMcpEndpoint,
  "BUNDJIL_EXECUTOR_MCP_URL"
);
const apiKeyConfig = Config.schema(
  Schema.Redacted(Schema.NonEmptyString),
  "BUNDJIL_EXECUTOR_API_KEY"
);

export const loadExecutorEndpoint = Effect.fn("ExecutorConfig.loadEndpoint")(
  function* () {
    return yield* endpointConfig;
  },
  (effect) =>
    effect.pipe(
      Effect.mapError(
        () =>
          new ExecutorConnectionConfigError({
            message: "ExecutorConnectionConfigError: loadEndpoint",
            operation: "loadEndpoint",
            reason: "Executor MCP endpoint configuration is invalid.",
          })
      )
    )
);

export const loadExecutorApiKey = Effect.fn("ExecutorConfig.loadApiKey")(
  function* () {
    return yield* apiKeyConfig;
  },
  (effect) =>
    effect.pipe(
      Effect.mapError(
        () =>
          new ExecutorConnectionConfigError({
            message: "ExecutorConnectionConfigError: loadApiKey",
            operation: "loadApiKey",
            reason: "Executor MCP credential configuration is invalid.",
          })
      )
    )
);

export const ExecutorConfigProviderLayer = ConfigProvider.layer(
  ConfigProvider.fromEnv()
);
# Bundjil

You are Bundjil, a minimal personal agent for this workspace.

Operate conservatively:

- Use the `workspace_status` tool when asked what this repo can do, which packages exist, or how the current agent slice is wired.
- Use `connection_search` to find the Executor connection when a request needs a connected service. Inspect its `skills` before selecting a named operation, then call `execute` only for an operation exposed by that connection.
- Treat Executor policy as authoritative. Approved reads may complete immediately; browser-gated operations must pause for the authenticated human decision and may be resumed only with the returned execution identifier.
- Never infer approval from message text, invent an approval decision, expose credentials or provider payloads, or use another provider path when Executor blocks or fails.
- Treat tool results as authoritative workspace context.
- Do not claim Cloudflare email, Notion, Vercel Connect, or memory features exist yet.
- Keep responses concise and explicit about any missing runtime credentials.
import { assert, it } from "@effect/vitest";
import { ConfigProvider, Effect, Redacted, Schema } from "effect";

import {
  ExecutorConnectionConfigError,
  ExecutorMcpEndpoint,
  loadExecutorApiKey,
  loadExecutorEndpoint,
} from "../agent/lib/executor/config.js";

const validEndpoint =
  "https://executor.sh/mcp/toolkits/bundjil-test?elicitation_mode=browser";
const syntheticKey = "executor-config-synthetic-secret";

it.effect(
  "loads a browser-mode Executor toolkit endpoint and redacted key",
  () =>
    Effect.gen(function* testExecutorConfig() {
      const endpoint = yield* loadExecutorEndpoint().pipe(
        Effect.provide(
          ConfigProvider.layer(
            ConfigProvider.fromEnv({
              env: { BUNDJIL_EXECUTOR_MCP_URL: validEndpoint },
            })
          )
        )
      );
      const key = yield* loadExecutorApiKey().pipe(
        Effect.provide(
          ConfigProvider.layer(
            ConfigProvider.fromEnv({
              env: { BUNDJIL_EXECUTOR_API_KEY: syntheticKey },
            })
          )
        )
      );

      assert.strictEqual(endpoint.href, validEndpoint);
      assert.strictEqual(Schema.is(ExecutorMcpEndpoint)(endpoint), true);
      assert.strictEqual(
        Schema.is(Schema.Redacted(Schema.NonEmptyString))(key),
        true
      );
      assert.strictEqual(Redacted.value(key), syntheticKey);
    })
);

it.effect(
  "rejects every endpoint form outside the browser-mode toolkit policy",
  () =>
    Effect.gen(function* testExecutorEndpointPolicy() {
      for (const endpoint of [
        "http://executor.sh/mcp/toolkits/bundjil-test?elicitation_mode=browser",
        "https://example.test/mcp/toolkits/bundjil-test?elicitation_mode=browser",
        "https://executor.sh:8443/mcp/toolkits/bundjil-test?elicitation_mode=browser",
        "https://executor.sh/mcp?elicitation_mode=browser",
        "https://executor.sh/mcp/toolkits/?elicitation_mode=browser",
        "https://user@executor.sh/mcp/toolkits/bundjil-test?elicitation_mode=browser",
        "https://executor.sh/mcp/toolkits/bundjil-test?elicitation_mode=browser#fragment",
        "https://executor.sh/mcp/toolkits/bundjil-test",
        "https://executor.sh/mcp/toolkits/bundjil-test?elicitation_mode=browser&elicitation_mode=browser",
        "https://executor.sh/mcp/toolkits/bundjil-test?elicitation_mode=model",
        "https://executor.sh/mcp/toolkits/bundjil-test?elicitation_mode=native",
        "https://executor.sh/mcp/toolkits/bundjil-test?elicitation_mode=unknown",
        "https://executor.sh/mcp/toolkits/bundjil-test?elicitation_mode=browser&allow_model_resume=true",
        "https://executor.sh/mcp/toolkits/bundjil-test?elicitation_mode=browser&extra=value",
      ]) {
        const error = yield* loadExecutorEndpoint().pipe(
          Effect.provide(
            ConfigProvider.layer(
              ConfigProvider.fromEnv({
                env: { BUNDJIL_EXECUTOR_MCP_URL: endpoint },
              })
            )
          ),
          Effect.flip
        );

        assert.strictEqual(
          Schema.is(ExecutorConnectionConfigError)(error),
          true
        );
        assert.strictEqual(error.operation, "loadEndpoint");
        assert.strictEqual(
          error.reason,
          "Executor MCP endpoint configuration is invalid."
        );
        assert.notInclude(String(error), endpoint);
      }
    })
);

it.effect("sanitizes missing endpoint and credential failures", () =>
  Effect.gen(function* testMissingExecutorConfig() {
    const endpointError = yield* loadExecutorEndpoint().pipe(
      Effect.provide(ConfigProvider.layer(ConfigProvider.fromEnv({ env: {} }))),
      Effect.flip
    );
    const keyError = yield* loadExecutorApiKey().pipe(
      Effect.provide(ConfigProvider.layer(ConfigProvider.fromEnv({ env: {} }))),
      Effect.flip
    );

    assert.strictEqual(
      Schema.is(ExecutorConnectionConfigError)(endpointError),
      true
    );
    assert.strictEqual(endpointError.operation, "loadEndpoint");
    assert.notInclude(String(endpointError), syntheticKey);
    assert.strictEqual(
      Schema.is(ExecutorConnectionConfigError)(keyError),
      true
    );
    assert.strictEqual(keyError.operation, "loadApiKey");
    assert.notInclude(String(keyError), syntheticKey);
  })
);
import { execFile, execFileSync } from "node:child_process";

import { assert, it } from "@effect/vitest";
import { Data, Effect, Match } from "effect";

import connection from "../agent/connections/executor.js";

class ExecutorConnectionTestError extends Data.TaggedError(
  "ExecutorConnectionTestError"
)<{
  reason: string;
}> {}

const syntheticEndpoint =
  "https://executor.sh/mcp/toolkits/bundjil-test?elicitation_mode=browser";
const syntheticKey = "executor-connection-synthetic-secret";
const bunExecutable =
  typeof Bun === "undefined"
    ? execFileSync("which", ["bun"], { encoding: "utf-8" }).trim()
    : (Bun.which("bun") ?? "bun");

const runExecutorConnectionSubprocess = Effect.fn(
  "ExecutorConnectionTest.runSubprocess"
)(function* (probe: "import" | "missing-key" | "synthetic-key") {
  const env =
    probe === "synthetic-key"
      ? {
          BUNDJIL_EXECUTOR_API_KEY: syntheticKey,
          BUNDJIL_EXECUTOR_MCP_URL: syntheticEndpoint,
        }
      : { BUNDJIL_EXECUTOR_MCP_URL: syntheticEndpoint };
  const source = Match.value(probe).pipe(
    Match.when("import", () => 'import "./agent/connections/executor.js";'),
    Match.when("missing-key", () =>
      [
        'import connection from "./agent/connections/executor.js";',
        "const auth = connection.auth;",
        'if (!auth || typeof auth === "function" || !("getToken" in auth)) throw new Error("expected static bearer authentication");',
        'const failure = await auth.getToken({ connection: { url: connection.url }, principal: { type: "app" } }).then(() => undefined, (error) => error);',
        "const renderedFailure = String(failure);",
        'if (failure === undefined || !renderedFailure.includes("ExecutorConnectionConfigError") || !renderedFailure.includes("loadApiKey") || renderedFailure.includes("BUNDJIL_EXECUTOR_API_KEY")) throw new Error("expected sanitized missing-key error");',
      ].join("\n")
    ),
    Match.when("synthetic-key", () =>
      [
        'import connection from "./agent/connections/executor.js";',
        "const auth = connection.auth;",
        'if (!auth || typeof auth === "function" || !("getToken" in auth)) throw new Error("expected static bearer authentication");',
        'const token = await auth.getToken({ connection: { url: connection.url }, principal: { type: "app" } });',
        'if (token.token.length !== 36) throw new Error("expected adapter bearer");',
      ].join("\n")
    ),
    Match.exhaustive
  );

  const output = yield* Effect.callback<
    Readonly<{ stderr: string; stdout: string }>,
    ExecutorConnectionTestError
  >((resume) => {
    const child = execFile(
      bunExecutable,
      ["--eval", source],
      {
        cwd: `${import.meta.dirname}/..`,
        encoding: "utf-8",
        env,
      },
      (error, stdout, stderr) => {
        resume(
          error === null
            ? Effect.succeed({ stderr, stdout })
            : Effect.fail(
                new ExecutorConnectionTestError({
                  reason: "Executor connection executable-edge proof failed.",
                })
              )
        );
      }
    );

    return Effect.sync(() => {
      child.kill();
    });
  });
  assert.notInclude(output.stdout, syntheticKey);
  assert.notInclude(output.stderr, syntheticKey);
});

it.effect(
  "defines the app-scoped Executor connection at the adapter edge",
  () =>
    Effect.gen(function* testExecutorConnection() {
      assert.deepStrictEqual(connection.tools, {
        allow: ["skills", "execute", "resume"],
      });
      const { auth, approval, headers } = connection;
      assert.strictEqual(approval, undefined);
      assert.strictEqual(headers, undefined);
      if (!auth || typeof auth === "function" || !("getToken" in auth)) {
        assert.fail("Expected static bearer authentication.");
      } else {
        assert.strictEqual(auth.principalType, "app");
      }

      yield* runExecutorConnectionSubprocess("import");
      yield* runExecutorConnectionSubprocess("missing-key");
      yield* runExecutorConnectionSubprocess("synthetic-key");
    }).pipe(Effect.withSpan("ExecutorConnectionTest.definition"))
);
# bundjil

Bundjil is a personal-agent workspace. The goal is to build a durable agent
that can meet a person in the channels they already use, starting with
iMessage and email, while reaching into trusted personal systems such as Notion
through scoped runtime integrations.

The name comes from Bundjil, also commonly spelt Bunjil, a creator figure in
Victorian Aboriginal traditions who is often represented as a wedge-tailed
eagle. Bunjil Place describes Bunjil as the creator spirit whose stories are
connected to Boon Wurrung, Bunurong, and Wurundjeri peoples, and whose eagle
form inspired the building's protective roof line. This project uses the name
as a respectful reference point for building a watchful and useful personal
agent; it is not an attempt to speak for those traditions.

## Product Direction

Bundjil is planned around a simple product shape:

- Agent runtime: Vercel Eve, where an agent is a directory of Markdown
  instructions, optional skills, TypeScript tools, channels, connections,
  schedules, and subagents.
- iMessage channel: Sendblue for programmable iMessage/SMS/RCS delivery and
  inbound webhooks.
- Email channel: Cloudflare Email Routing and Workers email handlers for
  programmable inbound email processing.
- Connected tools: Vercel Connect for short-lived, project-scoped access to
  Notion and other third-party systems without long-lived provider secrets in
  the app runtime.
- Domain model: Effect for fallible, async, stateful, boundary-crossing, and
  dependency-injected code.

The current repository ships a Production Eve agent, private Codex subscription
proxy, and Sendblue channel. Cloudflare email, Vercel Connect, and Notion remain
future integrations. Preview remains an independently retained environment;
its earlier proofs are historical evidence, not the current Production state.

## Current Packages

- `@bundjil/core` owns framework-neutral personal-agent domain primitives and
  Effect programs.
- `@bundjil/effect-start` owns reusable TanStack Start middleware glue for
  running Effect HTTP programs.
- `@bundjil/eve-effect` owns Eve-facing Effect Schema contracts, tagged
  errors, named operation services, and the Standard Schema bridge used by Eve
  tools.
- `@bundjil/codex-oauth` owns the Codex subscription profile/token lifecycle,
  trusted-local loopback PKCE login, encrypted profile envelope, fenced
  persistence and refresh services, direct Codex Responses proof surface, and
  opt-in Upstash Redis `KeyValueStore` adapter. It does not own a hosted
  browser OAuth callback or account-linking flow.
- `@bundjil/codex-proxy` is the private Effect HTTP proxy app. It exposes
  `GET /health` and a bearer-token-protected
  `POST /v1/chat/completions` route with explicit mock, local, and live
  compositions. The Vercel project is `bundjil-codex-proxy` in Cooper's
  personal Vercel account, not Tilt Legal.
- `@bundjil/agent` is the committed Vercel Eve app. It defines the root agent,
  instructions, the `workspace_status` tool that delegates into
  `@bundjil/eve-effect`, and app-owned model-provider config. Gateway is the
  default model path; Codex proxy mode is opt-in.

## Sendblue Channel State

`apps/agent` owns the Sendblue custom Eve channel, including its Effect Schema
contracts, redacted Config, explicit Layers, authentication, identity policy,
opaque routing, replay claims, and provider client. The public route is
`POST /eve/v1/sendblue/webhook` on accepted Production and retained Preview
deployments.

Sendblue authenticates at the route with its shared `sb-signing-secret` header,
not a body HMAC. Vercel's bypass is separate platform authentication and does
not authenticate the route. Only direct allowlisted iMessage events are
dispatched; ignored or duplicate events receive `200`, malformed authenticated
input gets `400`, failed route authentication gets `401`, unavailable durable
claims get `503`, and accepted dispatch gets `202`.

Production evidence records one provider-originated inbound, a 15-event Eve
replay through `session.waiting`, one private proxy completion, and one
`DELIVERED` outbound. A provider replay was suppressed without another
dispatch, proxy completion, or delivery. Production and Preview each retain a
receive webhook; route probes, durable replay fixtures, inventories, and leak
scans are recorded only as sanitized status/count evidence. See
[`apps/agent/README.md`](./apps/agent/README.md) for configuration ownership,
monitoring, and rollback. The earlier Preview proof remains historical.

`apps/agent` owns Eve filesystem runtime shape and deployment concerns.
Reusable app operations live in packages once the boundary is stable.

## Codex Provider State

Implemented:

- AI Gateway remains the default Eve model provider.
- `apps/agent` can opt into a private Codex proxy `LanguageModel` with
  `REDACTED`.
- `mock` is the default proxy mode for local smoke tests and safe preview
  rollback. It never calls Codex.
- `local` is an explicit encrypted filesystem proof. It runs only in trusted
  local Bun and Vercel rejects it.
- `live` is the hosted composition used by the private Production proxy and
  retained Preview proofs. A trusted-local
  loopback PKCE login writes an encrypted refresh-capable profile to Upstash;
  the proxy refreshes under a distributed lock with fenced commits, retries one
  classified unauthorized response, and fails closed for absent or unusable
  credentials.
- Production Eve proof establishes the deployed Eve -> private live proxy ->
  Codex provider path. Gateway remains the default model provider unless the
  app-owned configuration selects the opt-in proxy.

Operational constraints:

- Access-token-only import intentionally excludes refresh and ID tokens. It is
  a deprecated emergency/local diagnostic fallback, not normal hosted
  operation; use trusted-local subscription login for a refresh-capable
  profile.
- Production uses independently configured encrypted Vercel bindings, a
  separate encrypted profile/cipher/namespace, and a private bearer. OAuth
  login remains trusted-local; Vercel has no OAuth start or callback route.
- The operator runbook is in
  [`apps/codex-proxy/README.md`](./apps/codex-proxy/README.md). It records only
  sanitized statuses and leak booleans.

Unsupported paths:

- Do not treat Codex OAuth tokens as OpenAI Platform API keys or Vercel AI
  Gateway credentials.
- Do not use `OPENAI_API_KEY`, `CODEX_API_KEY`, or `@vercel/kv` for the
  subscription-backed provider path.
- Do not expose `apps/codex-proxy` as a public gateway.
- Do not deploy `bundjil-codex-proxy` to Tilt Legal.
- The Vercel proxy exposes no hosted browser OAuth callback, OAuth start route,
  or account-linking endpoint. Interactive login stays on the trusted local
  owner machine through a loopback PKCE callback.
- Gateway remains the default. The optional adapter is implemented through
  app-owned Effect Config, but its proof is separate from hosted live proxy
  proof.

## Getting Started

```bash
bun install
bun run build
bun run test
bun run verification
```

Use Bun from the repository root. During iteration, run the smallest useful
check first, then run `bun run verification` before handing work back.

For the local Eve app:

```bash
bun run --filter @bundjil/agent test
bun run --filter @bundjil/agent dev:no-ui
```

`eve dev --no-ui` serves the app at `http://127.0.0.1:2000` by default for
`eve@0.20.0`. Use `GET /eve/v1/info`, `POST /eve/v1/session`, and
`GET /eve/v1/session/:sessionId/stream` for local HTTP verification.

For the private Codex proxy app:

```bash
bun run --filter @bundjil/codex-proxy check-types
bun run --filter @bundjil/codex-proxy test
bun run --filter @bundjil/codex-proxy build
bun run --filter @bundjil/codex-proxy smoke-test
```

The proxy smoke test starts a local Bun server on an ephemeral port, verifies
`GET /health`, and verifies authenticated mock OpenAI-compatible SSE without
calling Codex.

The Codex proxy runbook is deliberately separate from Eve. It covers
trusted-local subscription login, Production and historical Preview proof,
refresh/re-login, deprecated local import diagnostics, monitoring, and ordered
rollback without exposing credentials or request content.

## Layout

```text
apps/
  agent/             Vercel Eve app and workspace_status tool.
  codex-proxy/       Private Effect HTTP proxy for Codex provider proof.
packages/
  core/              Framework-neutral Bundjil domain primitives.
  codex-oauth/       Codex OAuth profiles and direct Codex Responses proof.
  effect-start/      TanStack Start adapter for Effect HTTP programs.
  eve-effect/        Effect contracts and services for Eve tool boundaries.
docs/
  README.md          Documentation index.
  architecture/
    effect-patterns.md
    eve-agent.md     Eve app architecture and verification guide.
    repo-structure.md
    testing-and-quality.md
ARCHITECTURE.md      Agent architecture and package boundary overview.
```

## Development Rules

- Start with [Effect Patterns](./docs/architecture/effect-patterns.md) before
  adding schemas, services, config, layers, or provider wrappers.
- Use [Repo Structure](./docs/architecture/repo-structure.md) when deciding
  where code belongs.
- Use [Testing And Quality](./docs/architecture/testing-and-quality.md) to pick
  the narrowest useful check and the final verification gate.
- Before adding a new app, channel, provider integration, or durable package
  boundary, draft a SPEC through `$prd-writer` and implement through
  `$prd-implementer`.
- Every implementation task that touches Effect runtime, provider, app, or
  storage behavior must record the mandatory 3-pass Effect TS audit:
  ownership/call graph, implementation quality, and verification coverage.
- JSON string boundaries in app/package code must use Effect Schema codecs such
  as `Schema.fromJsonString(...)` and `Schema.UnknownFromJsonString`.

## Roadmap

1. Keep Gateway as the default Eve model provider while Codex proxy remains
   opt-in.
2. Keep Gateway as default unless app-owned configuration selects the
   Production-proven Codex proxy path.
3. Define channel-neutral message, identity, consent, and task contracts in
   `@bundjil/core`.
4. Keep the Production Sendblue channel and its retained Preview counterpart
   healthy through route, replay, inventory, monitoring, and rollback checks.
5. Add the Cloudflare email ingress path.
6. Connect Notion through Vercel Connect and model the first personal workflows.
7. Add readback, observability, and replayable verification for every channel.

## References

- [Bunjil the creator - Bunjil Place](https://www.bunjilplace.com.au/our-story/bunjil-creator)
- [eve - The Agent Framework - Vercel](https://vercel.com/eve)
- [Sendblue documentation](https://docs.sendblue.com/)
